      "g_parlamento_vistos_2026_expl": "O Parlamento aprovou a Lei 61/2025 e o DL 37-A/2024 que extinguiram definitivamente a regularização a partir de turista (Manifestação de Interesse). A obtenção de Visto de Residência no Consulado de origem é agora 100% obrigatória antes da viagem para Portugal.",
