      "bnk_step1_q": "Qual é a sua situação de residência em Portugal?",
      "bnk_step1_desc": "Bancos aplicam regras estritas de conformidade de acordo com a sua residência fiscal legal.",
      "bnk_opt_resident": "Residente Legal (com título ou manifestação)",
      "bnk_opt_resident_desc": "Abertura de conta padrão com direitos plenos.",
      "bnk_opt_nonresident": "Não-Residente (sem título português)",
      "bnk_opt_nonresident_desc": "Conta com passaporte e NIF de não-residente.",
      "bnk_step2_alert_title": "Regras Estritas de KYC (Know Your Customer)",
      "bnk_step2_alert_text": "Para evitar fraudes, é obrigatório apresentar comprovativo de atividade profissional (contrato, recibos ou início de atividade) ou comprovativo de fundos para ativar a conta.",
      "bnk_options_title": "🏬 Opções Bancárias: Físicos vs. Digitais",
      "bnk_options_desc": "• Bancos Tradicionais Físicos (CGD, Millennium BCP, Santander, Novo Banco, BPI): Atendimento presencial no balcão, ideais para depósitos em numerário e cheques. Podem exigir comissões de manutenção mensais (3€ a 7€/mês).\n• Bancos Digitais & Fintechs (Revolut, N26, Moey!, ActivoBank): Abertura rápida 100% online via app, 0€ de taxa de manutenção na maioria das contas, ótimos para câmbio e transferências internacionais gratuitas.",
      "bnk_tips_title": "⚠️ Dicas Importantes: Evitar Rejeições & Comissões",
      "bnk_tips_desc": "• Evite Rejeições: Apresente passaporte/título válido, NIF definitivo e comprovativo de morada com menos de 90 dias (fatura de água/luz/gás ou atestado de residência da Junta).\n• Comprovativo de Atividade: Contrato de trabalho, recibo de vencimento, declaração de início de atividade nas Finanças ou comprovativo de matrícula garante a aprovação rápida.\n• Isenção de Comissões: Domicilie o seu vencimento/salário para anular comissões de manutenção mensais na maioria dos bancos presenciais.",
      "bnk_smb_title": "🛡️ Direitos de Conta Básica (Serviços Mínimos Bancários - SMB)",
      "bnk_smb_desc": "Por lei em Portugal (Decreto-Lei n.º 27C/2000), qualquer cidadão residente legal tem direito a uma conta de Serviços Mínimos Bancários (SMB) em qualquer banco nacional.\n\n🛡️ Custo Máximo Regulado: No máximo 1% do IAS por ano (cerca de 5,09€/ano ou menos de ~0,43€/mês).\n✨ Inclui: Cartão de débito gratuito, acesso ao Homebanking/App, débitos diretos e até 25 transferências MB WAY gratuitas por mês.\n💡 Requisito: Não possuir outra conta à ordem em bancos portugueses (ou converter a sua conta existente em SMB).",
      "req_income_proof_bank": "Comprovativo de Rendimentos / Contrato de Trabalho / Recibos",
      "req_deposit": "Montante de depósito inicial mínimo (varia por banco)",
      "abertura_conta_bancaria": "Ficha de Cliente para Abertura de Conta",
      "abertura_conta_bancaria_desc": "Formulário de perfil do cliente para a abertura de conta bancária oficial em Portugal.",
      "abertura_conta_bancaria_expl": "Formulário exigido pelas instituições de crédito portuguesas para conhecer o perfil do cliente e o propósito da relação financeira.",
      "abertura_conta_bancaria_purpose": "Instruir o processo de abertura de conta bancária em território nacional.",
      "abertura_conta_bancaria_tips": "Apresente sempre um comprovativo de morada de utilidade pública recente e comprovativos de rendimentos ou contrato de trabalho.",
