      "nif_title": "NIF — Número de Identificação Fiscal",
      "nif_subtitle": "Portal das Finanças · AT",
      "nif_step1_q": "Reside legalmente em Portugal?",
      "nif_step1_desc": "A sua situação de residência determina quais os documentos necessários e o tipo de NIF (residente vs. não-residente).",
      "nif_opt_resident": "Sim, resido em Portugal",
      "nif_opt_resident_sub": "Portador de Autorização de Residência (AR) ou Visto válido",
      "nif_opt_nonresident": "Não resido em Portugal",
      "nif_opt_nonresident_sub": "Precisará de Representante Fiscal em Portugal",
      "nif_info_box": "O NIF é obrigatório para abrir conta bancária, celebrar contratos, trabalhar e aceder a serviços públicos.",
      "nif_where_label": "Onde Obter",
      "nif_where_resident": "Dirija-se a qualquer Serviço de Finanças com marcação prévia ou online via Portal das Finanças.",
      "nif_where_nonresident": "Precisa de um Representante Fiscal português. Pode pedir online com o Procurador via Portal das Finanças.",
      "nif_docs_needed": "Documentos Necessários",
      "nif_doc_passport": "Passaporte ou BI válido",
      "nif_doc_address": "Comprovativo de Morada",
      "nif_doc_ar": "Autorização de Residência (AR) ou Visto",
      "nif_doc_fiscal_rep": "Representante Fiscal (pessoa singular ou empresa)",
      "nif_doc_rep_id": "BI / NIF do Representante Fiscal",
      "nif_fill_doc": "Ver e Preencher",
      "nif_reset": "Recomeçar",
      "nif_rep_fiscal_title": "💡 Dicas & Life Hacks do Representante Fiscal",
      "nif_rep_fiscal_desc": "O Representante Fiscal é obrigatório para não-residentes de fora da UE/EEE. Ele atua como ligação com o Fisco.\n\n🛡️ Alerta de Responsabilidade: O representante tem responsabilidade subsidiária pelos seus impostos. Por isso, muitos amigos recusam e agências cobram taxas anuais.\n\n⚡ Life Hack: Morada Portuguesa = Remoção Grátis! Assim que tiver o seu título de residência ou contrato de arrendamento registado, atualize a sua morada no Portal das Finanças. O representante é removido imediatamente de forma 100% gratuita!\n\n💡 Poupe Centenas: Evite pagar taxas anuais de representação fiscal a intermediários. Qualquer residente legal em Portugal pode ser o seu representante fiscal de graça através de uma procuração simples.",
      "nif_rep_viactt_title": "⚡ Opcionalidade via Notificações Eletrónicas (Via CTT)",
      "nif_rep_viactt_desc": "Desde julho de 2022 (Despacho 8/2022-XXIII), a nomeação de representante fiscal é opcional para não-residentes se ativarem as notificações eletrónicas. Ao obter a sua senha das Finanças, adira à Caixa Postal Eletrónica (Via CTT) ou aos Canais de Notificação no Portal para dispensar o representante legalmente!",
      "nif_rep_address_title": "🏠 Morada Portuguesa = Remoção Automática & Grátis",
      "nif_rep_address_desc": "Assim que tiver um contrato de arrendamento registado ou o seu Título de Residência, altere a sua morada fiscal para Portugal no Portal das Finanças. O representante associado é exonerado instantaneamente sem qualquer custo.",
      "nif_rep_friend_title": "👥 Amigo ou Familiar Residente (Evite Taxas de Agências)",
      "nif_rep_friend_desc": "Qualquer residente legal em Portugal (incluindo estrangeiros com residência) pode ser o seu representante fiscal gratuitamente. Não pague taxas anuais de €150-€300 a agências. Basta assinar uma declaração de representação simples e entregar com os documentos do seu amigo.",
      "nif_rep_alert_title": "🛡️ Alerta de Responsabilidade para o Representante",
      "nif_rep_alert_desc": "O representante fiscal é responsável subsidiário (co-responsável) pelo pagamento dos seus impostos em Portugal. É por este risco legal que muitos amigos hesitam e as agências cobram caro. Ao explicar que os irá remover rapidamente, dará maior tranquilidade aos seus amigos.",
      "nif_rep_steps_title": "📋 Passo-a-Passo de Remoção no Portal das Finanças",
      "nif_rep_steps_desc": "1. Aceda ao Portal das Finanças e inicie sessão com o seu NIF e senha.\n2. No motor de busca do Portal, escreva 'Alterar Morada Fiscal' e selecione o serviço.\n3. Introduza a sua nova morada portuguesa e envie o comprovativo (e.g. contrato de arrendamento ou atestado da Junta).\n4. Após a validação pela Autoridade Tributária, o representante fiscal é removido automaticamente do seu perfil.",
      "nif_taxation_header": "Fiscalidade",
      "nif_guide_hacks_title": "💡 Guia Completo & Life Hacks",
      "nif_badge_optional": "Opcional",
      "nif_badge_address": "Morada Hack",
      "nif_badge_free": "Gratuito",
      "nif_badge_liability": "Responsabilidade",
      "nif_badge_step_by_step": "Passo-a-passo",
      "jobs_visa_guide_title": "🧭 Guia Atualizado do Visto de Trabalho & Procura de Emprego em Portugal (2025/2026)",
      "jobs_visa_guide_sub": "Informações essenciais e novas regras oficiais para trabalhar legalmente em Portugal",
      "jobs_visa_guide_btn_read": "Ler Guia de Visto",
      "jobs_visa_guide_btn_start": "Iniciar Jornada de Visto",
      "jobs_visa_guide_financial_title": "💰 Meios de Subsistência Exigidos (SMN 2025/2026)",
      "jobs_visa_guide_financial_desc": "Deverá comprovar a posse de meios de subsistência equivalentes a pelo menos 3 Salários Mínimos Nacionais (SMN) (€2.760 no valor de 920€/mês). Esta comprovação pode ser dispensada se apresentar um Termo de Responsabilidade assinado por um cidadão português ou residente legal em Portugal com rendimentos comprovados.",
      "jobs_visa_guide_steps_title": "📋 Requisitos Consulares & Novas Regras de Entrada",
      "jobs_visa_guide_steps_desc": "🚨 ATENÇÃO: A Manifestação de Interesse (Art. 88/89 n.º 2) foi DEFINITIVAMENTE REVOGADA pelo Governo. É OBRIGATÓRIO obter o Visto Prévio no Consulado/VFS do seu país de origem antes de viajar para Portugal.\n\n📋 Passo-a-Passo Obrigatório:\n1. Registo no Portal do IEFP: Para o Visto de Procura de Trabalho, é obrigatório efetuar a inscrição prévia no IEFP de Portugal e guardar a Declaração de Manifestação de Interesse.\n2. Documentos Consulares: Formulário preenchido, Passaporte válido (mínimo 6 meses), Registo Criminal do país de origem apostilado, Seguro de Viagem e Comprovativo de Alojamento em Portugal.\n3. Meios Financeiros: €2.760 em conta ou Termo de Responsabilidade de residente em Portugal.\n4. Cidadãos CPLP: Têm procedimento consular simplificado com isenção de parecer prévio da AIMA e taxas reduzidas.\n5. Agendamento AIMA Automático: Ao ser emitido o visto no consulado, é atribuída automaticamente a data e hora de agendamento na AIMA em Portugal para recolha de biometria e emissão do Título de Residência.",
      "niss_title": "NISS — Número de Identificação de Seg. Social",
      "niss_subtitle": "Segurança Social Direta",
      "niss_step1_q": "Qual a sua situação laboral?",
      "niss_step1_desc": "O tipo de registo na Segurança Social depende da sua relação de trabalho.",
