      "sns_inscricao_desc": "Declaração de pedido de inscrição no Serviço Nacional de Saúde (SNS) para atribuição de número de utente.",
      "expl_sns_inscricao": "A declaração de inscrição no SNS permite solicitar o registo no Centro de Saúde da sua área de residência e obter o Número de Utente para aceder aos cuidados de saúde públicos em Portugal.",
