      "irn_nacionalidade_casamento": "Nacionalidade Portuguesa por Casamento ou União de Facto",
      "irn_nacionalidade_casamento_desc": "Pedido de aquisição da nacionalidade portuguesa para cônjuges ou unidos de facto com cidadãos portugueses há mais de 3 anos.",
      "expl_irn_nacionalidade_casamento": "Permite obter a cidadania por via matrimonial. Exige certidão de casamento/união averbada e prova de ligação à comunidade.",
