      "aima_ar_art122": "Special Residence Cases (Art. 122)",
      "aima_ar_art122_desc": "Residence request by visa waiver (e.g., children in PT, health).",
      "aima_ar_art122_expl": "Article 122 covers special cases of residence visa waiver, such as humanitarian reasons, health, or strong family ties in national territory.",
      "aima_ar_art122_purpose": "Direct legalization in Portugal for situations of family or personal exception.",
      "aima_ar_art122_tips": "Consult a specialist to identify which of the 18 items applies to you.",
      "aima_ar_humanitaria": "Residence for Humanitarian Reasons",
      "aima_ar_humanitaria_desc": "Residence permit application under the international protection regime.",
      "aima_ar_humanitaria_expl": "Specific protection for individuals in situations of extreme vulnerability or risk in their home countries.",
      "aima_ar_humanitaria_purpose": "Legal protection for reasons of grave risk or asylum.",
      "aima_ar_humanitaria_tips": "CPR follow-up is highly recommended.",
      "aima_ar_renovacao": "Residence Authorization Renewal",
      "aima_ar_renovacao_desc": "Request to renew the residence title before its expiration.",
      "aima_ar_renovacao_expl": "Renewal must be requested between 90 and 30 days before your current title expires to avoid irregularity and fines.",
      "aima_ar_renovacao_purpose": "Renewal of the current residence title validity.",
      "aima_ar_renovacao_tips": "Automatic renewal on the portal is much faster.",
      "aima_ar_temp": "Residence Authorization Request",
      "aima_ar_temp_desc": "Official model for requesting a Temporary Residence Authorization.",
      "aima_ar_temp_expl": "Obtaining a residence permit in Portugal now follows a stricter regime after the 2024-2026 legal changes.\n\n• **WARNING:** The former 'Expression of Interest' (Art. 88 and 89) has been **abolished**. It is no longer possible to regularize your status if you entered as a tourist.\n\n• **Step 1: Residence Visa:** You must obtain a long-term visa (type D) at the Portuguese consulate in your home country before traveling.\n\n• **Step 2: Residence Permit:** Once in Portugal, you must convert your visa into a residence permit at AIMA.\n\nMain Visas:\n• **Work (D1/D3)**: Signed contract from origin.\n• **Job Search Visa**: Legal entry to look for work.\n• **Digital Nomad (D8)**: Remote work.\n• **CPLP**: Facilitated regime for Portuguese-speaking countries.",
      "aima_ar_temp_purpose": "Initial granting of legal residence in Portuguese territory.",
      "aima_ar_temp_tips": "Check if your passport is valid for more than 6 months.",
      "loc_aima": "AIMA prioritizes appointments through the digital portal. We recommend keeping your documents scanned in PDF for immediate submission.",
      "general_disclaimer_note": "DISCLAIMER: The information provided is for guidance only and does not replace legal advice. Always confirm on the official aima.gov.pt portal.",
      "docs_ready_desc": "Your document has been successfully generated and is ready for download.",
      "aima_asilo_req": "International Protection Request",
      "aima_asilo_req_desc": "Initial form for asylum application due to persecution or armed conflict.",
      "aima_asilo_req_expl": "First formal step for those fleeing political, religious persecution, or armed conflicts, ensuring immediate protection.",
      "aima_asilo_req_purpose": "Request for international protection from the Portuguese State.",
      "aima_asilo_req_tips": "Can be requested at any border post or PSP/GNR station.",
      "aima_audiencia_previa": "Prior Hearing Response",
      "aima_audiencia_previa_desc": "Draft pronouncement to respond to an Intent to Refuse Letter.",
      "aima_audiencia_previa_expl": "When AIMA threatens to archive the process, you typically have 10 business days to speak (Prior Hearing Right) or add missing documents.",
      "aima_audiencia_previa_purpose": "Stop the legal archiving of a process in AIMA.",
      "aima_audiencia_previa_tips": "The clock starts ticking a few days after the date on the envelope. Don't miss the deadline!",
      "aima_dec_alojamento": "Accommodation Declaration",
      "aima_dec_alojamento_desc": "Document where a legal resident certifies that they provide accommodation to the migrant.",
      "aima_dec_alojamento_expl": "This document is required when you do not have a rental contract in your name, serving as proof that you have a place to live.",
      "aima_dec_alojamento_purpose": "Prove address to the immigration authorities.",
      "aima_dec_alojamento_tips": "The owner or tenant must sign and attach a copy of the ID.",
      "aima_dec_responsabilidade": "Family Responsibility Statement",
      "aima_dec_responsabilidade_desc": "Statement where the resident is responsible for the costs of the relative to be reunited.",
      "aima_dec_responsabilidade_expl": "Used in family reunification to ensure the applicant has the means to support their dependents.",
      "aima_dec_responsabilidade_purpose": "Legal family reunification under the responsibility of the resident.",
      "aima_dec_responsabilidade_tips": "Must have a signature recognized in person.",
      "aima_dec_sustento": "Proof of Subsistence Means",
      "aima_dec_sustento_desc": "Proof under oath of the possession of means of subsistence.",
      "aima_dec_sustento_expl": "Proof that you have financial means (salary, savings, or income) to maintain yourself in Portugal without relying on state support.",
      "aima_dec_sustento_purpose": "Demonstrate financial autonomy before the State.",
      "aima_dec_sustento_tips": "Attach bank statements for the last 3 months.",
      "aima_deferimento_tacito": "Tacit Approval Draft",
      "aima_deferimento_tacito_desc": "Legal petition to force a response after the 90-day CPA legal period.",
      "aima_deferimento_tacito_expl": "The Code of Administrative Procedure protects you when the State exceeds legal deadlines without a decision. Use this draft to invoke tacit approval.",
      "aima_deferimento_tacito_purpose": "Force card issuance due to missed deadlines.",
      "aima_deferimento_tacito_tips": "Always send via Registered Mail with Acknowledgment of Receipt.",
      "aima_refugiado_status": "Residence Card for Refugees",
      "aima_refugiado_status_desc": "Issuance of residence title after refugee status granting.",
      "aima_refugiado_status_expl": "Final title issued after official recognition of refugee status by the Portuguese State.",
      "aima_refugiado_status_purpose": "Officialization of the granted international protection.",
      "aima_refugiado_status_tips": "Exempt from issuance fees.",
      "aima_renewal": "Residence Renewal",
