      "edu_step1_q": "Which education level do you want to revalidate?",
      "edu_step1_desc": "Select whether you want to request equivalency for secondary education or recognition of a higher academic degree.",
      "edu_step1_desc_v3": "Select whether you want to request secondary equivalency, higher degree recognition, or child enrollment & basic/secondary equivalency.",
      "edu_step2_alert_title": "Attention to Deadlines and Costs",
      "edu_step2_alert_text": "Higher education recognition has variable fees. ⚠️ SOVEREIGNTY ALERT: Under the recent Decree-Law n.º 83/2026 promulgated by the President, all foreign higher education institutions operating in Portugal must be officially registered with the IES to combat fraud. Ensure your diploma and transcripts have the Hague Apostille and are translated if applicable.",
      "edu_step2_alert_kids_title": "School Enrollment in Portugal (2026)",
