      "sef_declaracao_entrada_desc": "Proof of entry into national territory to be submitted upon arrival.",
      "expl_sef_declaracao_entrada": "The declaration of entry is mandatory for citizens entering Portugal through an uncontrolled border (e.g. from another Schengen country) and must be submitted within 3 business days.",
      "sef_declaracao_entrada_purpose": "Legalize your presence in national territory after arrival.",
      "sef_declaracao_entrada_tips": "Keep your physical or electronic travel ticket to attach as proof.",
