      "wiz_voluntary_return_title": "VOLUNTARY RETURN PROGRAM (ARVoRE VIII)",
      "wiz_voluntary_return_desc": "The ARVoRE VIII project (coordinated by IOM Portugal and AIMA) supports migrants wishing to return voluntarily to their country of origin. It offers counseling, support in obtaining documents, payment of airfare, and airport assistance.",
      "wiz_voluntary_return_step1": "Contact IOM Portugal by email (arvore@iom.int / retornovoluntario@iom.int) or phone (+351 21 324 2940) to schedule a free and confidential counseling session.",
      "wiz_voluntary_return_step2": "Submit the required documentation: Passport (even if expired), signed Consent/Interest Declaration, and proof of vulnerability (if applicable).",
      "wiz_voluntary_return_step3": "After validation of the request by IOM and AIMA, prepare the journey. The program will cover the flight ticket, airport taxes, and provide assistance upon departure and arrival in the destination country.",
      "wiz_voluntary_return_note": "⚠️ CRITICAL INFORMATION (Entry Ban): Voluntary return funded by the Portuguese State implies an entry ban to Portugal for a period of 3 years, registered in the SIS (Schengen Information System), unless the support value is fully reimbursed or in exceptional humanitarian cases duly validated.",
      "wiz_voluntary_return_links_title": "IOM Portal & Information",
      "wiz_voluntary_return_links_desc": "Register on the official Voluntary Return portal or consult the reintegration support programs.",
