      "business_plan_d2": "Plan de Negocios Simplificado - Visado D2",
      "business_plan_d2_desc": "Esquema simple del plan de negocios para justificar la viabilidad del proyecto en Portugal.",
      "business_plan_d2_expl": "El Plan de Negocios para el Visado D2 debe demostrar la viabilidad económica y financiera del proyecto, justificando su inversión.",
      "business_plan_d2_purpose": "Solicitud de visado consular D2 o permiso de residencia para emprendedores.",
      "business_plan_d2_tips": "Sea realista sobre el monto de inversión y los empleos a crear.",
      "at_inicio_atividade_draft": "Declaración de Inicio de Actividad (Borrador)",
      "at_inicio_atividade_draft_desc": "Borrador de preparación con todos los datos para rellenar en Hacienda.",
