      "aima_ar_temp": "Solicitud de Autorización de Residencia Temporal",
      "aima_ar_temp_desc": "Modelo oficial para solicitud de Autorización de Residencia Temporal.",
      "aima_ar_temp_expl": "A partir de 2025 y 2026, la concesión de residencia legal en Portugal se rige por un marco legal más estricto, enfocado en la inmigración cualificada y el control riguroso.\n\n• **Visado Consular Previo**: La regla general es la necesidad de obtener un visado de residencia adecuado en el consulado portugués de su país de origen antes de viajar. Las manifestaciones de interés directamente en Portugal se han vuelto excepcionales.\n\n• **Nuevas Reglas AIMA**: La Agencia para la Integración, Migraciones y Asilo (AIMA) exige que todas las solicitudes de permiso de residencia se presenten completas, con toda la documentación requerida, desde el primer momento. Ya no se aceptan procesos incompletos para ser completados posteriormente.\n\n• **Tipos de Visado**: Los visados para búsqueda de trabajo se han restringido a profesionales altamente cualificados. Otras vías, como la reagrupación familiar o los visados para nacionales de la CPLP, tienen ahora requisitos más exigentes, como la necesidad de un visado consular específico.\n\n• **Proceso General**: El procedimiento estándar implica solicitar el visado consular, viajar a Portugal y, posteriormente, formalizar la solicitud del permiso de residencia ante la AIMA.",
      "aima_ar_temp_purpose": "Concesión inicial de residencia legal en territorio portugués.",
      "aima_ar_temp_tips": "Verifique si su pasaporte tiene una validez superior a 6 meses.",
      "loc_aima": "AIMA está procesando las citas prioritariamente a través del portal digital. Recomiendo que mantengas tus documentos escaneados en PDF para su presentación inmediata.",
      "general_disclaimer_note": "AVISO: La información proporcionada es orientativa y no sustituye el asesoramiento jurídico. Confirme siempre en el portal oficial aima.gov.pt.",
      "docs_ready_desc": "Su documento ha sido generado con éxito y está listo para ser descargado.",
      "aima_asilo_req": "Solicitud de Protección Internacional",
      "aima_asilo_req_desc": "Formulario inicial para asilo por persecución o conflicto armado.",
      "aima_asilo_req_expl": "Primer paso formal para quienes huyen de guerra o persecución directa.",
      "aima_asilo_req_purpose": "Solicitud de protección internacional al Estado Portugués.",
      "aima_asilo_req_tips": "Puede solicitarse en cualquier puesto fronterizo o comisaría de PSP/GNR.",
      "aima_audiencia_previa": "Respuesta en Audiencia Previa",
      "aima_audiencia_previa_desc": "Minuta de pronunciamiento para responder a una Carta de Intención de Denegación.",
      "aima_audiencia_previa_expl": "Cuando la AIMA amenaza con archivar el proceso, tienes 10 días hábiles para pronunciarte (Derecho de Audiencia Previa).",
