      "edu_step2_alert_title": "Atención a Plazos y Costos",
      "edu_step2_alert_text": "El reconhecimento de educación superior tiene tasas variables. ⚠️ ALERTA DE SOBERANÍA: Bajo el reciente Decreto-Ley n.º 83/2026 promulgado por el Presidente, todas las instituciones extranjeras de educación superior que operan en Portugal deben registrarse en el IES para combatir fraudes. Asegúrate de que el diploma y el historial académico tengan la Apostilla de La Haya y estén traducidos si corresponde.",
