      "drv_title": "Canje de Licencia de Conducir",
      "drv_subtitle": "IMT — Conducir en Portugal",
      "drv_step1_q": "¿Cuál es el origen de su licencia de conducir?",
      "drv_step1_desc": "El país emisor y la legislación aprobada en el Parlamento determinan los acuerdos legales vigentes para la validez o necesidad de canje.",
      "drv_opt_cplp": "Licencia CPLP (Brasil, PALOPs, etc.)",
      "drv_opt_cplp_desc": "Conducción directa permitida en Portugal sin exámenes. Canje opcional para conducir en la UE.",
      "drv_opt_ocde": "País OCDE / Acuerdo Bilateral (EE.UU., Reino Unido, Suiza, etc.)",
      "drv_opt_ocde_desc": "Conducción permitida en territorio nacional sin requerir examen práctico o teórico.",
      "drv_opt_other": "Otros Países (Sin Acuerdo Bilateral)",
      "drv_opt_other_desc": "Canje en el IMT según el tiempo de residencia (sin examen hasta 2 años de residencia).",
      "drv_opt_tvde": "Certificación TVDE (Uber, Bolt)",
      "drv_opt_tvde_desc": "Licencia profesional obligatoria para transporte individual de pasajeros en vehículos.",
      "drv_step2_alert_title": "Certificado Médico Electrónico e IMT Online",
      "drv_step2_alert_text": "Para enviar la solicitud en el IMT Online, el médico transmite automáticamente el Certificado Médico Electrónico al IMT a través de la plataforma DGS. No es necesario presentar papel.",
      "drv_parliament_title": "Actualización Legislativa: Reglas IMT y Parlamento",
      "drv_parliament_cplp_note": "🇧🇷🇦🇴🇵TU Acuerdo CPLP y OCDE (Decreto Ley n.º 46/2022): Los titulares de licencias de conducir válidas de la CPLP y OCDE emitidas hace menos de 15 años y menores de 60 años están exentos de canje obligatorio para conducir en Portugal y exentos de exámenes.",
      "drv_parliament_eu_warning": "⚠️ Validez Territorial Exclusiva: Conducir con la licencia de origen solo es válido en territorio portugués. Para conducir en otros países de la Unión Europea o espacio Schengen, el canje en el IMT Online es obligatorio (tasa de 30€).",
      "drv_parliament_deadlines": "📅 Plazos para Países Sin Acuerdo: Hasta 90 días de residencia (conducción libre); de 90 días a 2 años (canje en el IMT sin examen); de 2 a 5 años (canje con examen práctico); más de 5 años (proceso completo en autoescuela).",
