      "acc_opt_buying": "Comprar Casa",
      "acc_opt_buying_desc": "Guía de CPCV, Crédito Hipotecario, Impuestos (IMT) y Escritura.",
      "badge_propriedade": "Propiedad",
      "badge_state_support": "Apoyos Públicos",
      "acc_supports_badge": "Apoyo del Estado",
      "acc_supports_procedures": "Trámites y Solicitud",
      "acc_supports_docs": "Documentos Necesarios",
      "acc_supports_back": "Volver a los Programas",
      "acc_supports_subtitle": "Programas de Apoyo Estatal — Trámites y Solicitudes",
      "acc_supports_select_prompt": "Seleccione un programa para ver detalles, documentos y trámites",
      "acc_step2_alert_title": "Registro de Contratos y Atestado",
      "acc_step2_alert_text": "En 2026, todos los contratos de alquiler deben ser registrados en Hacienda por el arrendador. El Atestado de la Junta es la prueba de dirección soberana más aceptada en Portugal.",
      "junta_atestado_residencia": "Solicitud de Atestado de Residencia — Junta de Freguesia",
      "junta_atestado_residencia_desc": "Solicitud formal de certificado de residencia ante la Junta de Freguesia de su zona de vivienda.",
      "junta_atestado_residencia_expl": "El certificado de residencia es el documento oficial que acredita su domicilio fiscal en Portugal, exigido por Finanzas, AIMA y bancos.",
      "junta_atestado_residencia_purpose": "Probar legalmente su domicilio y residencia efectiva en la parroquia.",
      "junta_atestado_residencia_tips": "Si no dispone de contrato de alquiler registrado, necesitará la firma de dos testigos empadronados en la misma parroquia.",
      "at_declaracao_cedencia": "Declaración de Cesión de Alojamiento y Morada Familiar",
      "at_declaracao_cedencia_desc": "Declaración bajo compromiso de honor del propietario del inmueble autorizando el alojamiento familiar.",
      "at_declaracao_cedencia_expl": "Utilizada ante Finanzas para asociar su NIF a un domicilio cedido gratuitamente por un familiar o conocido.",
      "at_declaracao_cedencia_purpose": "Regularizar el domicilio fiscal ante la Autoridad Tributaria sin necesidad de un contrato de arrendamiento comercial.",
      "at_declaracao_cedencia_tips": "Debe estar firmada por el propietario o arrendatario principal del inmueble y acompañada del registro de la propiedad o contrato correspondiente.",
      "bnk_title": "Apertura de Cuenta Bancaria",
      "bnk_subtitle": "Bancos en Portugal — KYC y Registro",
      "bnk_step1_q": "¿Cuál es su situación de residencia en Portugal?",
      "bnk_step1_desc": "Los bancos aplican reglas estrictas de cumplimiento según su residencia fiscal legal.",
      "bnk_opt_resident": "Residente Legal (con título o recibo de AIMA)",
      "bnk_opt_resident_desc": "Apertura de cuenta estándar con plenos derechos.",
      "bnk_opt_nonresident": "No Residente (sin título portugués)",
      "bnk_opt_nonresident_desc": "Cuenta con pasaporte y NIF de no residente.",
      "bnk_step2_alert_title": "Reglas Estrictas de KYC (Conozca a su Cliente)",
      "bnk_step2_alert_text": "Para evitar fraudes, es obligatorio presentar comprobante de actividad profesional (contrato, nóminas o inicio de actividad) o comprobante de fondos para activar la cuenta.",
      "bnk_options_title": "🏬 Opciones Bancarias: Físicos vs. Digitales",
      "bnk_options_desc": "• Bancos Tradicionales Físicos (CGD, Millennium BCP, Santander, Novo Banco, BPI): Atención presencial en ventanilla, ideales para depósitos en efectivo y cheques. Pueden exigir comisiones de mantenimiento mensuales (3€ a 7€/mes).\n• Bancos Digitales y Fintechs (Revolut, N26, Moey!, ActivoBank): Apertura rápida 100% online vía app, 0€ de tasa de mantenimiento en la mayoría de cuentas, excelentes para cambio de divisas y transferencias gratuitas.",
      "bnk_tips_title": "⚠️ Consejos Importantes: Evitar Rechazos y Comisiones",
      "bnk_tips_desc": "• Evite Rechazos: Presente pasaporte/título válido, NIF definitivo y comprobante de domicilio de menos de 90 días (factura de luz/agua o certificado de empadronamiento/junta).\n• Comprobante de Actividad: Contrato de trabajo, nómina, declaración de inicio de actividad o certificado de matrícula escolar garantiza la aprobación rápida.\n• Exención de Comisiones: Domicilie su nómina/salario para eliminar comisiones mensuales de mantenimiento en la mayoría de bancos tradicionales.",
      "bnk_smb_title": "🛡️ Derechos de Cuenta Básica (Serviços Mínimos Bancários - SMB)",
      "bnk_smb_desc": "Por ley en Portugal (Decreto-Ley n.º 27C/2000), todo ciudadano residente legal tiene derecho a una cuenta de Servicios Mínimos Bancarios (SMB) en cualquier banco nacional.\n\n🛡️ Coste Máximo Regulado: Máximo el 1% del IAS al año (aprox. 5,09€/año o menos de ~0,43€/mes).\n✨ Incluye: Tarjeta de débito gratuita, acceso a Homebanking/App, débitos directos y hasta 25 transferencias MB WAY gratuitas al mes.\n💡 Requisito: No tener otra cuenta corriente en bancos portugueses (o convertir su cuenta existente a SMB).",
      "req_income_proof_bank": "Comprobante de Ingresos / Contrato de Trabajo / Nóminas",
      "req_deposit": "Monto de depósito inicial mínimo (varía según el banco)",
      "abertura_conta_bancaria": "Ficha de Cliente para Apertura de Cuenta",
      "abertura_conta_bancaria_desc": "Formulario de perfil de cliente para apertura de cuenta bancaria oficial en Portugal.",
      "abertura_conta_bancaria_expl": "Formulario requerido por las instituciones de crédito portuguesas para conocer el perfil del cliente y el propósito de la relación financiera.",
      "abertura_conta_bancaria_purpose": "Iniciar el proceso de apertura de cuenta bancaria en el territorio nacional.",
      "abertura_conta_bancaria_tips": "Presente siempre un justificante de domicilio de servicios públicos reciente y comprobantes de ingresos o contrato de trabajo.",
      "jornadas_essentials_label": "Esenciales",
      "jornadas_nif_sub": "Finanzas · AT",
