      "nif_step1_desc": "Su situación de residencia determina los documentos necesarios y el tipo de NIF.",
      "nif_opt_resident": "Sí, resido en Portugal",
      "nif_opt_resident_sub": "Titular de Permiso de Residencia (AR) o Visa válida",
      "nif_opt_nonresident": "No resido en Portugal",
      "nif_opt_nonresident_sub": "Necesitará un Representante Fiscal en Portugal",
      "nif_info_box": "El NIF es obligatorio para abrir cuenta bancaria, celebrar contratos, trabajar y acceder a servicios públicos.",
