      "nif_where_resident": "Diríjase a cualquier Oficina de Hacienda con cita previa o en línea vía el Portal de Hacienda.",
      "nif_where_nonresident": "Necesita un Representante Fiscal portugués. Puede solicitarlo en línea con un apoderado.",
      "nif_docs_needed": "Documentos Necesarios",
      "nif_doc_passport": "Pasaporte o DNI válido",
      "nif_doc_address": "Comprobante de Domicilio",
      "nif_doc_ar": "Permiso de Residencia (AR) o Visa",
      "nif_doc_fiscal_rep": "Representante Fiscal (persona física o empresa)",
      "nif_doc_rep_id": "DNI / NIF del Representante Fiscal",
      "nif_fill_doc": "Ver y Rellenar",
      "nif_reset": "Empezar de Nuevo",
      "nif_rep_fiscal_title": "💡 Representante Fiscal: Consejos y Trucos",
      "nif_rep_fiscal_desc": "El Representante Fiscal es obligatorio para no residentes de fuera de la UE/EEE. Actúa como enlace con la Autoridad Tributaria.\n\n🛡️ Alerta de Responsabilidad: El representante tiene responsabilidad subsidiaria por sus impuestos. Por eso, muchos amigos lo evitan y las agencias cobran tarifas anuales.\n\n⚡ Life Hack: ¡Dirección Portuguesa = Remoción Gratis! Tan pronto como obtenga su permiso de residencia (AR) o contrato de alquiler registrado, actualice su dirección fiscal en el Portal das Finanças. ¡El representante se elimina al instante y de forma 100% gratuita!\n\n💡 Ahorre Cientos: Evite pagar tarifas anuales constantes de representación a intermediarios. Cualquier residente legal en Portugal puede actuar como su representante fiscal de forma gratuita usando un poder notarial simple.",
      "nif_rep_viactt_title": "⚡ Opcionalidad mediante Notificaciones Electrónicas",
      "nif_rep_viactt_desc": "Desde julio de 2022 (Decreto 8/2022-XXIII), el representante fiscal es opcional para no residentes si activan las notificaciones electrónicas. Al obtener su contraseña de Finanças, suscríbase al Buzón Postal Electrónico (Via CTT) o active los Canales de Notificación para eximirse legalmente.",
      "nif_rep_address_title": "🏠 Dirección Portuguesa = Remoción Gratis e Instantánea",
      "nif_rep_address_desc": "Tan pronto como tenga un contrato de alquiler registrado o su Tarjeta de Residencia, actualice su dirección fiscal a Portugal en el Portal das Finanças. El representante se elimina de inmediato de forma 100% gratuita.",
      "nif_rep_friend_title": "👥 Amigo o Familiar Residente (Evite Tarifas de Agencias)",
      "nif_rep_friend_desc": "Cualquier residente legal en Portugal (incluidos los extranjeros con residencia) puede ser su representante de forma gratuita. No pague tarifas anuales de €150-€300 a agencias. Solo firme una carta de representación simple y adjunte los documentos de su amigo.",
      "nif_rep_alert_title": "🛡️ Alerta de Responsabilidad Solidaria",
      "nif_rep_alert_desc": "El representante fiscal es responsable subsidiario (co-responsable) por sus obligaciones tributarias en Portugal. Debido a este riesgo legal, muchos amigos dudan y las agencias cobran caro. Explicarles que los retirará rápido les dará tranquilidad.",
      "nif_rep_steps_title": "📋 Paso a Paso para Eliminarlo en el Portal",
      "nif_rep_steps_desc": "1. Acceda al Portal das Finanças e inicie sesión con su NIF y contraseña.\n2. En la barra de búsqueda superior, busque 'Alterar Morada Fiscal' y seleccione el servicio.\n3. Introduzca su nueva dirección en Portugal y suba el comprobante (ej. contrato de alquiler o atestado de la Junta).\n4. Tras la validación de la Autoridad Tributaria, el representante fiscal se eliminará automáticamente.",
      "jobs_visa_guide_title": "🧭 Guía Actualizada de Visado de Trabajo y Búsqueda de Empleo en Portugal (2025/2026)",
      "jobs_visa_guide_sub": "Información esencial y nuevas reglas oficiales para trabajar legalmente en Portugal",
      "jobs_visa_guide_btn_read": "Leer Guía de Visados",
      "jobs_visa_guide_btn_start": "Iniciar Trámite de Visado",
      "jobs_visa_guide_financial_title": "💰 Medios de Subsistencia Requeridos (2025/2026)",
      "jobs_visa_guide_financial_desc": "Debe demostrar medios financieros equivalentes a al menos 3 Salarios Mínimos Nacionales (2.760 € sobre la base del SMN de 920 €/mes). Este requisito se puede eximir mediante la presentación de un Termo de Responsabilidade firmado por un ciudadano portugués o residente legal con ingresos comprobados en Portugal.",
      "jobs_visa_guide_steps_title": "📋 Requisitos Consulares y Reglas de Entrada",
      "jobs_visa_guide_steps_desc": "🚨 ADVERTENCIA: La Manifestación de Interés (Art. 88/89 nº 2) fue REVOCADA DEFINITIVAMENTE por el Gobierno. Es OBLIGATORIO obtener un Visado Previo en el Consulado/VFS de Portugal en su país de origen antes de viajar a Portugal.\n\n📋 Paso a Paso Obligatorio:\n1. Inscripción en el Portal del IEFP: Para la Visa de Búsqueda de Trabajo, la inscripción previa en el portal del IEFP de Portugal es obligatoria para obtener la declaración requerida.\n2. Documentos Consulares: Formulario de solicitud de visado, Pasaporte válido (mín. 6 meses), Antecedentes Penales del país de origen (apostillado), Seguro de Viaje y Comprobante de Alojamiento en Portugal.\n3. Medios Financieros: 2.760 € en cuenta bancaria o Termo de Responsabilidade de un residente en Portugal.\n4. Ciudadanos CPLP: Se benefician de trámites consulares simplificados sin necesidad de aprobación previa de AIMA y con tasas reducidas.\n5. Cita Automática en AIMA: Al emitirse el visado en el consulado, se asigna automáticamente una fecha de cita en AIMA en Portugal para la recogida de datos biométricos y expedición de la Tarjeta de Residencia.",
      "niss_title": "NISS — Número de Seguridad Social",
      "niss_subtitle": "Seguridad Social Directa",
