      "promessa_trabalho_art88_desc": "Borrador de promesa de contrato de trabajo para fines de regularización.",
      "expl_promessa_trabalho_art88": "La promesa de trabajo es un compromiso formal del empleador que permite demostrar la existencia de una relación laboral futura para efectos de visa o residencia.",
