      "ss_niss": "Solicitud del Número de Identificación de Seguridad Social (NISS)",
      "ss_niss_desc": "Asignación de número de Seguridad Social para ciudadanos extranjeros.",
      "expl_ss_niss": "El NISS es el número de identificación de la Seguridad Social en Portugal. Es indispensable para trabajar legalmente, cotizar y acceder a prestaciones y pensiones.",
