      "nif_req_desc": "Solicitud del Número de Identificación Fiscal para ciudadanos extranjeros.",
      "expl_nif_req": "El NIF es el número de contribuyente en Portugal, emitido por la Autoridad Tributaria. Es obligatorio para cualquier acto financiero o contractual, como abrir una cuenta bancaria o alquilar una casa.",
