      "aima_ar_temp": "Demande d'Autorisation de Résidence",
      "aima_ar_temp_desc": "Modèle officiel pour la demande de concession d'Autorisation de Résidence Temporaire.",
      "aima_ar_temp_expl": "L'obtention d'une première autorisation de résidence légale au Portugal pour un citoyen non-membre de l'UE/EEE/Suisse suit une procédure en deux étapes.\n\n• **Étape 1 : Visa de Résidence.** Vous devez d'abord obtenir un visa de résidence de long séjour (type D) auprès du consulat portugais de votre pays de résidence.\n\n• **Étape 2 : Titre de Séjour.** Une fois au Portugal, vous devez prendre rendez-vous avec l'AIMA pour convertir votre visa en un titre de séjour.\n\nLes principaux visas menant à la résidence sont :\n• **Travail salarié (D1/D3)** : Pour un contrat de travail avec une entreprise portugaise.\n• **Activité indépendante (D2)** : Pour créer une entreprise ou en tant qu'indépendant.\n• **Revenus passifs (D7)** : Pour les retraités ou titulaires de revenus stables.\n• **Nomade Digital (D8)** : Pour les télétravailleurs avec des revenus de source étrangère.",
      "aima_ar_temp_purpose": "Concession initiale de résidence légale sur le territoire portugais.",
      "aima_ar_temp_tips": "Vérifiez que votre passeport est valide pour plus de 6 mois.",
      "loc_aima": "L'AIMA traite les rendez-vous prioritairement via le portail numérique. Je recommande de conserver vos documents numérisés en PDF pour une soumission immédiate.",
