      "drv_opt_tvde_desc": "Permis professionnel obligatoire pour le transport individuel de passagers en véhicule.",
      "drv_step2_alert_title": "Certificat Médical Électronique & IMT Online",
      "drv_step2_alert_text": "Pour soumettre la demande sur IMT Online, le médecin transmet automatiquement le certificat médical électronique à l'IMT via la plateforme DGS. Aucun document papier n'est requis.",
      "drv_parliament_title": "Mise à Jour Législative : Règles IMT & Parlement",
      "drv_parliament_cplp_note": "🇧🇷🇦🇴🇵TU Accord CPLP & OCDE (Décret-Loi n° 46/2022) : Les titulaires de permis de conduire valides de la CPLP et de l'OCDE délivrés depuis moins de 15 ans et âgés de moins de 60 ans sont dispensés d'échange obligatoire pour conduire au Portugal et dispensés d'examens.",
      "drv_parliament_eu_warning": "⚠️ Validité Territoriale Exclusive : Conduire avec votre permis d'origine n'est valable qu'au Portugal. Pour conduire dans d'autres pays de l'Union européenne ou de l'espace Schengen, l'échange sur IMT Online est obligatoire (taxe de 30 €).",
      "drv_parliament_deadlines": "📅 Délais pour les Pays Sans Accord : Jusqu'à 90 jours de résidence (conduite libre) ; de 90 jours à 2 ans (échange à l'IMT sans examen) ; de 2 à 5 ans (échange avec examen pratique) ; après 5 ans (procédure complète en auto-école).",
