      "acc_step2_alert_title": "Enregistrement des Contrats et Attestation",
      "acc_step2_alert_text": "En 2026, tous les contrats de location doivent être enregistrés aux Finances par le propriétaire. L'attestation de la Junta est la preuve d'adresse souveraine la plus acceptée au Portugal.",
      "junta_atestado_residencia": "Demande d'Attestation de Résidence — Junta de Freguesia",
      "junta_atestado_residencia_desc": "Demande formelle d'attestation de résidence auprès de la Junta de Freguesia de votre zone d'habitation.",
      "junta_atestado_residencia_expl": "L'attestation de résidence est le document officiel qui prouve votre domicile fiscal au Portugal, exigé par les Finances, l'AIMA et les banques.",
      "junta_atestado_residencia_purpose": "Prouver légalement votre adresse et votre résidence effective dans la paroisse.",
