      "at_declaracao_cedencia_tips": "Elle doit être signée par le propriétaire ou locataire principal du bien et accompagnée du registre foncier ou du contrat correspondant.",
      "bnk_title": "Ouverture de Compte Bancaire",
      "bnk_subtitle": "Banques au Portugal — KYC & Inscription",
      "bnk_step1_q": "Quel est votre statut de résidence au Portugal ?",
      "bnk_step1_desc": "Les banques appliquent des règles de conformité strictes basées sur votre résidence fiscale légale.",
      "bnk_opt_resident": "Résident Légal (avec titre ou reçu AIMA)",
      "bnk_opt_resident_desc": "Ouverture de compte standard avec pleins droits.",
      "bnk_opt_nonresident": "Non-Résident (sans titre portugais)",
      "bnk_opt_nonresident_desc": "Compte avec passeport et NIF de non-résident.",
      "bnk_step2_alert_title": "Règles KYC (Know Your Customer) Strictes",
      "bnk_step2_alert_text": "Pour éviter la fraude, il est obligatoire de présenter un justificatif d'activité professionnelle (contrat, bulletins de salaire ou début d'activité) ou un justificatif de fonds pour activer le compte.",
      "bnk_options_title": "🏬 Options Bancaires: Physiques vs. Numériques",
      "bnk_options_desc": "• Banques Traditionnelles Physiques (CGD, Millennium BCP, Santander, Novo Banco, BPI): Service en agence en personne, idéal pour dépôts d'espèces et chèques. Peuvent facturer des frais mensuels (3€ à 7€/mois).\n• Banques Numériques & Fintechs (Revolut, N26, Moey!, ActivoBank): Ouverture 100% en ligne via app, 0€ de frais de tenue de compte sur la plupart des comptes, idéales pour le change et les transferts gratuits.",
      "bnk_tips_title": "⚠️ Conseils Importants: Éviter les Rejets & Frais",
      "bnk_tips_desc": "• Éviter les Rejets: Présentez un passeport/titre valide, NIF définitif et un justificatif de domicile de moins de 90 jours (facture de services publics ou certificat de résidence).\n• Justificatif d'Activité: Un contrat de travail, bulletin de salaire, déclaration de début d'activité ou certificat de scolarité garantit l'approbation rapide.\n• Exonération des Frais: Domiciliez votre salaire pour annuler les frais de tenue de compte mensuels dans la plupart des banques traditionnelles.",
      "bnk_smb_title": "🛡️ Droits au Compte Bancaire de Base (Serviços Mínimos Bancários - SMB)",
      "bnk_smb_desc": "Selon la loi au Portugal (Décret-Loi n° 27C/2000), tout citoyen résident légal a droit à un compte de Services Bancaires de Base (SMB - Serviços Mínimos Bancários) dans n'importe quelle banque nationale.\n\n🛡️ Coût Max Réglementé: Au maximum 1% de l'IAS par an (environ 5,09€/an ou moins de ~0,43€/mois).\n✨ Inclus: Carte de débit gratuite, accès Homebanking/App, prélèvements automatiques et jusqu'à 25 virements MB WAY gratuits par mois.\n💡 Condition: Ne pas posséder d'autre compte courant dans les banques portugaises (ou convertir votre compte existant en SMB).",
      "req_income_proof_bank": "Justificatif de Revenus / Contrat de Travail / Bulletins de Salaire",
      "req_deposit": "Montant du dépôt initial minimum (varie selon la banque)",
      "abertura_conta_bancaria": "Fiche Client pour l'Ouverture de Compte",
      "abertura_conta_bancaria_desc": "Formulaire de profil client pour l'ouverture d'un compte bancaire officiel au Portugal.",
      "abertura_conta_bancaria_expl": "Formulaire exigé par les établissements de crédit portugais pour connaître le profil du client et le but de la relation financière.",
