      "nif_docs_needed": "Documents Nécessaires",
      "nif_doc_passport": "Passeport ou Carte d'identité valide",
      "nif_doc_address": "Justificatif de Domicile",
      "nif_doc_ar": "Titre de Séjour (AR) ou Visa",
      "nif_doc_fiscal_rep": "Représentant Fiscal (personne physique ou entreprise)",
      "nif_doc_rep_id": "CNI / NIF du Représentant Fiscal",
      "nif_fill_doc": "Voir et Remplir",
      "nif_reset": "Recommencer",
      "nif_rep_fiscal_title": "💡 Représentant Fiscal : Astuces & Hacks",
      "nif_rep_fiscal_desc": "Un représentant fiscal est obligatoire pour les non-résidents hors UE/EEE. Il sert de liaison avec l'administration fiscale portugaise.\n\n🛡️ Alerte de Responsabilité : Le représentant est solidairement responsable de vos impôts. C'est pourquoi les proches peuvent hésiter et les agences facturent des frais annuels.\n\n⚡ Life Hack : Adresse Portugaise = Retrait Gratuit ! Dès que vous obtenez votre titre de séjour (AR) ou contrat de location enregistré, mettez à jour votre adresse dans le Portal das Finanças. Le représentant est retiré instantanément et 100% gratuitement !\n\n💡 Économisez des Centaines d'Euros : Évitez de payer des frais de représentation annuels à des intermédiaires. Tout résident légal au Portugal peut être votre représentant fiscal gratuitement via une simple procuration.",
      "nif_rep_viactt_title": "⚡ Retrait Optionnel via les Notifications Électroniques",
      "nif_rep_viactt_desc": "Depuis juillet 2022 (Décret 8/2022-XXIII), la désignation d'un représentant fiscal é facultative pour les non-résidents s'ils activent les notifications électroniques. Dès l'obtention de votre mot de passe, adhérez à la boîte postale électronique (Via CTT) ou activez les canaux de notification pour vous en dispense légalement !",
      "nif_rep_address_title": "🏠 Adresse Portugaise = Retrait Gratuit & Immédiat",
      "nif_rep_address_desc": "Dès que vous disposez d'un contrat de location enregistré ou de votre Titre de Séjour, modifiez votre adresse fiscale pour le Portugal sur le Portal das Finanças. Le représentant associé est immédiatement révoqué sans aucun frais.",
      "nif_rep_friend_title": "👥 Ami ou Proche Résident (Évitez les Frais d'Agence)",
      "nif_rep_friend_desc": "Tout résident légal au Portugal (y compris les étrangers résidents) peut être votre représentant fiscal gratuitement. Évitez de payer 150 à 300 € par an aux agences. Signez simplement une lettre de procuration simple et fournissez-la avec les documents de votre ami.",
      "nif_rep_alert_title": "🛡️ Risque de Responsabilité Solidaire du Représentant",
      "nif_rep_alert_desc": "Le représentant fiscal est solidairement responsable de vos obligations fiscales au Portugal. C'est à cause de ce risque juridique que les proches hésitent et les agences facturent cher. Rassurer vos amis sur le fait que vous les retirerez rapidement facilitera leur accord.",
      "nif_rep_steps_title": "📋 Guide Étape par Étape pour le Retrait en Ligne",
      "nif_rep_steps_desc": "1. Connectez-vous sur le Portal das Finanças avec votre NIF et mot de passe.\n2. Dans la barre de recherche du portail, recherchez 'Alterar Morada Fiscal' (Changement d'Adresse) et sélectionnez le service.\n3. Saisissez votre nouvelle adresse portugaise et téléchargez votre justificatif (ex: bail enregistré ou attestation de la mairie).\n4. Après validation par l'administration fiscale, le représentant fiscal est automatiquement retiré de votre dossier.",
      "jobs_visa_guide_title": "🧭 Guide Mis à Jour Visa de Travail & Recherche d'Emploi au Portugal (2025/2026)",
      "jobs_visa_guide_sub": "Informations essentielles et nouvelles règles officielles pour travailler légalement au Portugal",
      "jobs_visa_guide_btn_read": "Lire le Guide Visa",
      "jobs_visa_guide_btn_start": "Commencer la Procédure Visa",
      "jobs_visa_guide_financial_title": "💰 Moyens de Subsistance Requis (2025/2026)",
      "jobs_visa_guide_financial_desc": "Vous devez prouver des ressources correspondant à au moins 3 fois le Salaire Minimum National (2 760 € sur la base du SMN de 920 €/mois). Cette exigence peut être levée par une Déclaration de Prise en Charge (Termo de Responsabilidade) signée par un citoyen ou résident légal au Portugal avec des revenus prouvés.",
      "jobs_visa_guide_steps_title": "📋 Exigences Consulaires & Règles d'Entrée",
      "jobs_visa_guide_steps_desc": "🚨 AVERTISSEMENT : La Manifestation d'Intérêt (Art. 88/89 nº 2) a été DÉFINITIVEMENT ABROGÉE par le gouvernement. Il est OBLIGATOIRE d'obtenir un Visa Préalable auprès du Consulat/VFS du Portugal dans votre pays d'origine avant de voyager.\n\n📋 Procédure Obligatoire Étape par Étape :\n1. Inscription sur le Portail IEFP : Pour le Visa de Recherche d'Emploi, l'inscription préalable sur le portail de l'IEFP Portugal est obligatoire pour obtenir l'attestation requise.\n2. Documents Consulaires : Formulaire de demande de visa, Passeport valide (min. 6 mois), Extrait de Casier Judiciaire du pays d'origine (apostillé), Assurance Voyage et Justificatif de Logement au Portugal.\n3. Ressources Financières : 2 760 € sur compte bancaire ou Déclaration de prise en charge d'un résident au Portugal.\n4. Citoyens CPLP : Bénéficient d'un traitement consulaire simplifié sans accord préalable obligatoire de l'AIMA et avec des frais réduits.\n5. Rendez-vous Automatique AIMA : Lors de la délivrance du visa consulaire, une date de rendez-vous AIMA au Portugal est automatiquement attribuée pour la prise de données biométriques et la délivrance de la Carte de Séjour.",
      "niss_title": "NISS — Numéro de Sécurité Sociale",
