      "g_equivalencia_notas_expl": "Pour étudier ou travailler au Portugal, il est souvent nécessaire de convertir votre moyenne finale ou vos notes vers l'échelle portugaise officielle de 0 à 20 points (utilisée dans l'enseignement secondaire et supérieur). Ce guide présente les formules et les tableaux officiels des autorités portugaises.",
      "step_eq_1_title": "Identifier l'Échelle d'Origine",
      "step_eq_1_desc": "Vérifiez l'échelle officielle de votre pays d'origine. Exemples courants : Brésil (0 à 10), États-Unis et Royaume-Uni (A à F / GPA 0 à 4.0), France et PALOP (0 à 20), Italie (0 à 30 ou 0 à 110).",
      "step_eq_2_title": "Formule de Conversion Linéaire",
      "step_eq_2_desc": "La formule officielle au Portugal est : Note PT = 10 + [10 * (Note d'Origine - Note Minimale de Passage) / (Note Maximale - Note Minimale de Passage)]. Cela garantit que toute note de passage étrangère équivaut à au moins 10 points au Portugal.",
      "step_eq_3_title": "Apostiller ou Légaliser les Relevés",
      "step_eq_3_desc": "Pour que vos notes soient légalement valables au Portugal, vos relevés de notes doivent être apostillés (Apostille de La Haye) ou légalisés par le Consulat du Portugal dans le pays émetteur.",
      "step_eq_4_title": "Soumettre pour Équivalence Officielle",
      "step_eq_4_desc": "Soumettez votre demande sur le portail de la DGES (enseignement supérieur) ou dans un lycée public au Portugal (enseignement primaire et secondaire).",
      "faq_eq_1_q": "Comment fonctionne la conversion de l'échelle du Brésil (0 à 10) ?",
      "faq_eq_1_a": "La conversion officielle suit la formule linéaire : Note 10.0 (maximum) = 20 points ; Note 8.0 = 16 points ; Note 7.0 = 14 points ; Note 5.0 (note minimale de passage au Brésil) = 10 points.",
      "faq_eq_2_q": "Comment cela fonctionne-t-il pour le GPA américain (0 à 4.0) ou les notes A-F ?",
      "faq_eq_2_a": "Selon la loi portugaise, un GPA de 4.0 (A) équivaut à 20 points ; 3.0 (B) équivaut à 15 points ; 2.0 (C - note minimale de passage) équivaut à 10 points.",
      "faq_eq_3_q": "Où puis-je consulter les tableaux officiels complets par pays ?",
      "faq_eq_3_a": "Vous pouvez consulter les tableaux d'équivalence officiels par pays sur le site de la Direction générale de l'éducation (dge.mec.pt) en vertu du décret-loi n° 227/2005.",
