      "wiz_voluntary_return_desc": "Le projet ARVoRE VIII (coordonné par l'OIM Portugal et l'AIMA) soutient les migrants souhaitant retourner volontairement dans leur pays d'origine. Il offre des conseils, une aide pour l'obtention de documents, le paiement du billet d'avion et une assistance à l'aéroport.",
      "wiz_voluntary_return_step1": "Contacter l'OIM Portugal par e-mail (arvore@iom.int / retornovoluntario@iom.int) ou par téléphone (+351 21 324 2940) pour planifier une séance de conseil gratuite et confidentielle.",
      "wiz_voluntary_return_step2": "Soumettre les documents requis : Passeport (même s'il est expiré), Déclaration de Consentement/Intérêt signée, et preuve de vulnérabilité (le cas échéant).",
