export const t = (key: string, lang: string): string => {
  const l = (lang || 'pt').toLowerCase();
  const langGroup = TRANSLATIONS[l] || TRANSLATIONS.pt;
  return langGroup[key] || TRANSLATIONS.pt[key] || key;
};
